 /* Sound.java * * * * Created on 7 mai 2007, 01:48 * * * * To change this template, choose Tools | Template Manager * * and open the template in the editor. * */package net.sf.jiga.xtended.impl;/** *  * this interface is intended to have the sound effects loaded with. *  * @author www.b23prodtm.info *  */public interface Sound {    /** plays the sound*/    void play();    /** loops playing     * @param b dis/enables looping (e.g. background music)     */    void setRepeatEnabled(boolean b);    /**     * @return true or false, whether looping play is enabled or not, resp.     */    boolean isRepeatEnabled();    /** loads the sound     * @param filename the file path to the sound file     */    boolean load(String filename);    /** stops playing the sound*/    void stop();}